import re
pairs=[]
for rec in u:
    text=rec['message']['content'][0]['text']
    for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n',text):
        num,hh,ww=map(int,m.groups()); pos=m.end(); rows=[]
        for line in text[pos:].splitlines()[:hh]: rows.append([int(z) for z in line.split()])
        rest=text[pos:]; outm=re.search(rf'Demo pair {num} output \({hh}x{ww}\):\n',rest)
        if not outm: print('missing output',num); continue
        opos=pos+outm.end(); outs=[]
        for line in text[opos:].splitlines()[:hh]: outs.append([int(z) for z in line.split()])
        pairs.append((num,rows,outs))
print([(n,len(a),len(a[0]),len(b),all(len(r)==len(a[0]) for r in a+b)) for n,a,b in pairs])
